package com.vibecode.task.application;
import com.vibecode.output.domain.OutputAnalysisRecord; import com.vibecode.output.domain.OutputAnalysisStatus; import com.vibecode.task.domain.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class TaskCompletionPolicy { public boolean canComplete(List<TaskDependencyRecord> deps, Map<UUID,WorkflowTask> tasks, List<TaskAcceptanceCriterionRecord> criteria, OutputAnalysisRecord latest){return deps.stream().allMatch(d->tasks.containsKey(d.dependencyTaskId())&&tasks.get(d.dependencyTaskId()).status()==WorkflowTaskStatus.COMPLETED)&&criteria.stream().filter(TaskAcceptanceCriterionRecord::required).allMatch(c->c.status()==CriterionStatus.SATISFIED)&&latest!=null&&latest.status()==OutputAnalysisStatus.SUCCESS;} }
